INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 17, 'theory', 'Quiz: cloud and cost');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 0, 'Which pricing model suits a constant baseline load?', '["Spot", "Reserved for 1–3 years with a discount of about 40%", "On demand only", "Free"]', 1, 'A constant load is predictable, and the discount for the commitment pays off; peaks go on demand.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 1, 'What are spot instances good for?', '["A single database", "Batch jobs and workers that tolerate interruption", "DNS", "Storing passwords"]', 1, 'Spot is 3–4 times cheaper but can be taken back within a minute.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 2, 'What is usually paid for in the cloud?', '["Inbound traffic", "Outbound and cross-region traffic", "A laptop''s idle time", "Creating tags"]', 1, 'Outbound traffic is expensive; a CDN, compression, and co-location lower the bill.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 3, 'What does infrastructure as code give you?', '["No servers", "Reproducibility, change review, and the ability to restore the environment", "More load", "Turning off monitoring"]', 1, 'A declarative description in the repository: changes go through review and the pipeline; drift is detected.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 17, 4, 'When are functions as a service not worth it?', '["For rare and uneven tasks", "For a steady, constantly high stream: ordinary servers are cheaper", "For handling upload events", "For webhooks"]', 1, 'Per-invocation pricing pays off at peaks and zero load, but a constant stream is cheaper on always-on servers.');
